<?php use App\Core\Money; ?>
<div class="sales-page"><div class="sales-hero"><h1><?= $isNew?'Create customer':'Edit customer' ?></h1><p>Keep customer identity, billing details and currency ready for every document.</p></div>
<?php $errors=flash('errors',[]); if($errors):?><div class="alert alert-error"><?php foreach($errors as $x):?><div><?=e($x)?></div><?php endforeach;?></div><?php endif;?>
