<div class="sales-field"><label>Customer code</label><input name="code" value="<?=e($row['code']??'')?>" required></div><div class="sales-field"><label>Company name</label><input name="company_name" value="<?=e($row['company_name']??'')?>" required autofocus></div><div class="sales-field"><label>Contact name</label><input name="contact_name" value="<?=e($row['contact_name']??'')?>"></div><div class="sales-field"><label>Email</label><input type="email" name="email" value="<?=e($row['email']??'')?>"></div><div class="sales-field"><label>Phone</label><input name="phone" value="<?=e($row['phone']??'')?>"></div><div class="sales-field"><label>Currency</label><select name="default_currency"><?php foreach(Money::CURRENCIES as $c=>$v):?><option value="<?=$c?>" <?=($row['default_currency']??'AED')===$c?'selected':''?>><?=e($c.' · '.$v['label'])?></option><?php endforeach;?></select></div><div class="sales-field wide"><label>Address</label><textarea name="address" rows="3" placeholder="Billing address"><?=e($row['address']??'')?></textarea></div><div class="sales-field"><label>Status</label><select name="status"><option value="active" <?=($row['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($row['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></div></div></div><div class="sales-actions"><a class="btn btn-ghost" href="<?=url('/admin/customers')?>">Back</a><button class="btn btn-primary">Save customer</button></div></form></div>
